{
  "packet_id": "H6-T04-1",
  "claim_id": "C022",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C022.component",
    "value": "Recruitment and analysis should stop at predeclared sample and follow-up limits.",
    "scope": "Prospective stopping bounds with unspecified values. The mapping does not explain their precedence relative to roster-linked follow-up plus grace.",
    "provenance": {
      "refs": [
        {
          "source_id": "P013",
          "role": "SUPPORT"
        },
        {
          "source_id": "P008",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans supply the stopping rule and the separate roster-linked follow-up requirement without resolving their interaction."
    }
  },
  "signal_basis": {
    "component_id": "C022.signal_basis",
    "value": "The prospective comparison observes publication outcomes within a common window, reports incomplete trajectories, and operates under predeclared recruitment and analysis limits. Follow-up also incorporates roster opportunities and grace periods; early stopping of exposure is separately restricted to predefined harm criteria.",
    "scope": "Procedural bounds on the planned observation and comparison; no particular numerical limit or adequacy of the resulting evidence is asserted.",
    "provenance": {
      "refs": [
        {
          "source_id": "P013",
          "role": "SUPPORT"
        },
        {
          "source_id": "P008",
          "role": "SUPPORT"
        },
        {
          "source_id": "P016",
          "role": "SUPPORT"
        },
        {
          "source_id": "P017",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The cited bundle supplies the prospective bounds, follow-up requirements, incomplete-trajectory reporting, comparison window, and separate exposure-stopping restriction."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C022.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "This bounded procedural claim requires no unresolved empirical relation."
    }
  },
  "rationale": "Following predeclared stopping bounds is warranted as a prospective comparison rule that limits outcome-dependent extension of recruitment or analysis. The claim does not assert that those bounds guarantee adequate evidence or resolve every follow-up conflict.",
  "uncertainty": "The numerical bounds and their precedence over roster-linked follow-up remain unspecified. This prevents determining a concrete stopping date, but does not defeat the explicitly limited procedural claim.",
  "anomalies": []
}
